'use strict';
let pmFeed=null,pmBusy=false,pmSelected=null,pmCurrentQuote=null,pmTimer,pmQuoteVersion=0,pmBookTimer;
const pmCents=n=>Number.isFinite(n)?(n*100).toFixed(1)+'¢':'—',pmPercent=n=>Number.isFinite(n)?(n*100).toFixed(1)+'%':'—';
function pmWords(s){return String(s||'').toLowerCase()}
function renderPredictions(){
 const q=pmWords($('#pmSearch').value),only=$('#pmConnected').checked,markets=(pmFeed?.value?.markets||[]).filter(m=>(!q||pmWords(m.question+' '+m.event).includes(q))&&(!only||m.connections.length));
 $('#pmStatus').textContent=pmFeed?.value?(pmFeed.stale?'Saved data · refresh failed':'Polymarket snapshot')+' · '+stamp(pmFeed.checkedAt)+' · '+markets.length+' contracts':pmFeed?.error?'Market data unavailable. Retry later; no prices are assumed.':'Loading political markets…';
 $('#pmCoverage').textContent=pmFeed?.value?.coverage||'Public market data. No wallet or real-money orders.';
 $('#pmMarkets').innerHTML=markets.map(predictionCard).join('')||`<p class="muted">${pmFeed?.value?'No contracts match these filters.':'No market feed available. Please retry later.'}</p>`;
 observePredictionCards();
}
async function loadPredictions(){if(pmBusy)return;pmBusy=true;clearTimeout(pmTimer);try{const r=await fetch('/api/predictions');if(!r.ok)throw Error();pmFeed=await r.json()}catch{pmFeed=pmFeed?.value?{...pmFeed,stale:true}:{error:true}}finally{pmBusy=false;renderPredictions();if(view==='predictions')pmTimer=setTimeout(loadPredictions,120000)}}
function pmConnectionHTML(m){return m.connections.length?m.connections.map(a=>`<article class="pm-evidence"><small>Shared topics: ${a.shared.map(esc).join(', ')} · ${date(a.date)}</small><h3>${esc(a.title)}</h3><p>${esc(a.summary)}</p><p><b>Equity implication:</b> ${esc(a.impact)}</p><p><b>Risk:</b> ${esc(a.risk)}</p><p><b>Next check:</b> ${esc(a.watch)}</p><div>${a.tickers.map(t=>`<button data-ticker="${esc(t)}">${esc(t)} ↗</button>`).join(' ')} ${a.sources.map((u,i)=>researchLink(u,'Evidence '+(i+1))).join(' · ')}</div></article>`).join(''):'<p class="muted">No recent briefing shares enough specific topics with this contract. Research is needed before estimating an edge.</p>'}
function pmInsightHTML(m){const a=m.insight;return `<section class="pm-insight"><h3>poor’s assessment</h3>${a?`<small>${stamp(a.createdAt)} · sourced inference</small><p><b>Connection:</b> ${esc(a.thesis)}</p><p><b>Counterargument:</b> ${esc(a.against)}</p><p><b>Already priced in?</b> ${esc(a.pricedIn)}</p><p><b>Next check:</b> ${esc(a.watch)}</p>${a.sources.map((u,i)=>researchLink(u,'Source '+(i+1))).join(' · ')}<p class="home-caption">Assessment reflects evidence at publication; compare with the latest prices below.</p>`:`<p>No current contract-specific assessment. Ask poor to investigate the evidence and settlement rules.</p><small>${esc(pmFeed?.researchStatus||'Not checked yet')}${pmFeed?.researchCheckedAt?' · '+stamp(pmFeed.researchCheckedAt):''}</small>`}</section>`}
function selectPrediction(id){const m=pmFeed?.value?.markets.find(m=>m.id===id);if(!m)return;pmSelected=m;pmCurrentQuote=null;renderPredictions();$('#pmDetail').hidden=false;$('#pmDetail').innerHTML=`<div class="pm-detail-heading"><h2>${esc(m.question)}</h2><button id="pmAsk">Ask poor ↗</button></div><p class="home-caption">Prices are market-implied odds, not poor’s probability estimate.</p><div class="pm-facts"><span>End date<b>${m.end?date(m.end):'Not supplied'}</b></span><span>Liquidity reported<b>$${m.liquidity===null?'—':Math.round(m.liquidity).toLocaleString()}</b></span><span>24h Yes move<b>${m.change===null?'—':(m.change>=0?'+':'')+(m.change*100).toFixed(1)+' pp'}</b></span></div><div id="pmHistory" class="pm-history">Loading 7-day Yes-price history…</div><details class="pm-rules"><summary>Resolution rules & source</summary><p>${esc(m.rules).replace(/\n/g,'<br>')}</p>${m.resolutionSource?researchLink(m.resolutionSource,'Resolution source'): '<p>Check the resolution source in the rules.</p>'} · ${researchLink(m.url,'Market rules on Polymarket')}</details>${typeof researchEvidenceReady==='function'&&researchEvidenceReady(m.investigation)&&typeof investigationCard==='function'?investigationCard(m.investigation,m.challenge):pmInsightHTML(m)}<h3>Related evidence · topic matches</h3>${pmConnectionHTML(m)}<h3>Current order book</h3><div class="pm-controls"><label>Outcome <select id="pmOutcome"><option>Yes</option><option>No</option></select></label><button id="pmQuoteRefresh">Refresh prices</button></div><div id="pmQuote" class="pm-quote" role="status"></div><p>${researchLink(m.url,'Open contract on Polymarket ↗')}</p>`;
 $('#pmOutcome').onchange=refreshPredictionQuote;$('#pmQuoteRefresh').onclick=refreshPredictionQuote;
 $('#pmAsk').onclick=()=>{const question='Investigate this prediction market using public evidence. Explain evidence for/against, what is priced in, uncertainty and the next check. Do not invent a probability. Contract: '+m.question+'; end: '+m.end+'; market snapshot: '+m.outcomes.map(o=>o.label+' '+pmPercent(o.price)).join(', ')+'; rules excerpt (retrieve the complete rules before concluding): '+m.rules.slice(0,650)+'; source: '+m.url;changeView('chat');$('#chatQuestion').value=question.slice(0,1800);$('#chatQuestion').focus()};
 loadPredictionHistory(m);refreshPredictionQuote();if(matchMedia('(max-width: 800px)').matches)$('#pmDetail').scrollIntoView({block:'start'});
}
async function loadPredictionHistory(m){try{const r=await fetch('/api/predictions/history?id='+m.id),d=await r.json();if(pmSelected?.id!==m.id)return;const points=d.value?.points;if(!r.ok||!points||points.length<2)throw Error();const first=points[0],last=points.at(-1),width=480,height=90,coords=points.map(x=>`${((x.t-first.t)/(last.t-first.t||1)*width).toFixed(1)},${(height-x.p*height).toFixed(1)}`).join(' ');const reactions=m.connections.map(a=>{const start=Date.parse(a.date+'T00:00:00Z')/1000,before=points.filter(x=>x.t<start).at(-1);return before&&start-before.t<=86400&&last.t>=start?`<p>${esc(a.title)}: ${pmPercent(before.p)} before source day → ${pmPercent(last.p)} latest sample. ${date(a.date)}</p>`:''}).join('');$('#pmHistory').innerHTML=`<small>Yes price · 7-day history · 0–100% scale${d.stale?' · stale':''}</small><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Seven-day Yes-price history"><line x1="0" x2="480" y1="45" y2="45" stroke="#dce6df" stroke-dasharray="3 4"/><polyline points="${coords}" fill="none" stroke="#198568" stroke-width="2"/></svg><small>${date(new Date(first.t*1000).toISOString())} · ${pmPercent(first.p)} → ${pmPercent(last.p)} · ${date(new Date(last.t*1000).toISOString())}</small>${reactions}<small>Historical samples are not executable quotes. Date-only news cannot establish the exact price reaction or causation.</small>`}catch{if(pmSelected?.id===m.id)$('#pmHistory').textContent='Price history unavailable; no trend is inferred.'}}
async function refreshPredictionQuote(){clearTimeout(pmBookTimer);const version=++pmQuoteVersion,id=pmSelected.id;pmCurrentQuote=null;$('#pmQuote').textContent='Checking order book…';try{const r=await fetch('/api/predictions/quote?id='+id+'&outcome='+$('#pmOutcome').value),d=await r.json();if(version!==pmQuoteVersion||pmSelected?.id!==id)return;if(!r.ok)throw Error(d.error||'Order book unavailable');pmCurrentQuote=d;const depth=rows=>rows.reduce((n,x)=>n+Number(x.price)*Number(x.size),0),spread=d.ask!==null&&d.bid!==null?d.ask-d.bid:null;$('#pmQuote').innerHTML=`<div class="pm-facts"><span>Buy ${esc(d.outcome.label)} · ask<b>${pmCents(d.ask)}</b></span><span>Sell ${esc(d.outcome.label)} · bid<b>${pmCents(d.bid)}</b></span><span>Spread<b>${pmCents(spread)}</b></span></div><p>Book checked ${stamp(Number(d.book.timestamp))}. Prices can change before execution.</p>${predictionExecutionHTML(d)}<details><summary>Available depth</summary><p>Asks $${Math.round(depth(d.book.asks)).toLocaleString()} · Bids $${Math.round(depth(d.book.bids)).toLocaleString()} across returned levels.</p><div class="pm-depth"><div><b>Asks · price / shares</b>${d.book.asks.slice(0,5).map(x=>`<p>${pmCents(x.price)} · ${Number(x.size).toLocaleString()}</p>`).join('')||'<p>No asks</p>'}</div><div><b>Bids · price / shares</b>${d.book.bids.slice(0,5).map(x=>`<p>${pmCents(x.price)} · ${Number(x.size).toLocaleString()}</p>`).join('')||'<p>No bids</p>'}</div></div></details><small>${d.market.feesEnabled?'Market fees apply.':'Check applicable fees on Polymarket.'} ${spread>.05?'Wide spread: the cost of entering and exiting matters.':''}</small>`}catch(e){if(version===pmQuoteVersion&&pmSelected?.id===id)$('#pmQuote').textContent=e.message}finally{if(version===pmQuoteVersion&&pmSelected?.id===id&&view==='predictions')pmBookTimer=setTimeout(()=>{if(view==='predictions'&&!document.hidden)refreshPredictionQuote()},30000)}}
if(typeof window!=='undefined'){
 window.addEventListener('hashchange',()=>{if(location.hash==='#predictions')changeView('predictions')});if(location.hash==='#predictions')changeView('predictions');
 $('#pmSearch').oninput=renderPredictions;$('#pmConnected').onchange=renderPredictions;$('#pmRefresh').onclick=loadPredictions;
 document.addEventListener('click',e=>{const market=e.target.closest('[data-pm-market]');if(market)selectPrediction(market.dataset.pmMarket)});
 document.addEventListener('visibilitychange',()=>{if(!document.hidden&&view==='predictions')loadPredictions()});
}
